<?php
 namespace Pterodactyl\Services\Dezerx; class Seo { public const PAGES = [ ['slug' => 'checkpoint', 'match' => '#^/auth/login/checkpoint#', 'label' => 'Two step check', 'group' => 'Account'], ['slug' => 'login', 'match' => '#^/auth/login#', 'label' => 'Sign in', 'group' => 'Account'], ['slug' => 'password', 'match' => '#^/auth/password#', 'label' => 'Reset your password', 'group' => 'Account'], ['slug' => 'api', 'match' => '#^/account/api#', 'label' => 'API credentials', 'group' => 'Account'], ['slug' => 'ssh', 'match' => '#^/account/ssh#', 'label' => 'SSH keys', 'group' => 'Account'], ['slug' => 'activity', 'match' => '#^/account/activity#', 'label' => 'Activity', 'group' => 'Account'], ['slug' => 'account', 'match' => '#^/account#', 'label' => 'Account', 'group' => 'Account'], ['slug' => 'files', 'match' => '#^/server/[^/]+/files#', 'label' => 'Files', 'group' => 'Server'], ['slug' => 'databases', 'match' => '#^/server/[^/]+/databases#', 'label' => 'Databases', 'group' => 'Server'], ['slug' => 'schedules', 'match' => '#^/server/[^/]+/schedules#', 'label' => 'Schedules', 'group' => 'Server'], ['slug' => 'users', 'match' => '#^/server/[^/]+/users#', 'label' => 'Subusers', 'group' => 'Server'], ['slug' => 'backups', 'match' => '#^/server/[^/]+/backups#', 'label' => 'Backups', 'group' => 'Server'], ['slug' => 'network', 'match' => '#^/server/[^/]+/network#', 'label' => 'Network', 'group' => 'Server'], ['slug' => 'startup', 'match' => '#^/server/[^/]+/startup#', 'label' => 'Startup', 'group' => 'Server'], ['slug' => 'settings', 'match' => '#^/server/[^/]+/settings#', 'label' => 'Settings', 'group' => 'Server'], ['slug' => 'plugins', 'match' => '#^/server/[^/]+/plugins#', 'label' => 'Plugins', 'group' => 'Server'], ['slug' => 'mods', 'match' => '#^/server/[^/]+/mods#', 'label' => 'Mods', 'group' => 'Server'], ['slug' => 'modpacks', 'match' => '#^/server/[^/]+/modpacks#', 'label' => 'Modpacks', 'group' => 'Server'], ['slug' => 'worlds', 'match' => '#^/server/[^/]+/worlds#', 'label' => 'Worlds', 'group' => 'Server'], ['slug' => 'players', 'match' => '#^/server/[^/]+/players#', 'label' => 'Players', 'group' => 'Server'], ['slug' => 'console', 'match' => '#^/server/[^/]+#', 'label' => 'Console', 'group' => 'Server'], ['slug' => 'dashboard', 'match' => '#^/$#', 'label' => 'Dashboard', 'group' => 'Panel'], ]; public const FALLBACK = ['slug' => 'panel', 'label' => 'Game panel', 'group' => 'Panel']; public static function config(): array { $theme = Theme::config(); return [ 'title' => (string) ($theme['seo.title'] ?? ''), 'description' => (string) ($theme['seo.description'] ?? ''), 'keywords' => (string) ($theme['seo.keywords'] ?? ''), 'robots' => (string) ($theme['seo.robots'] ?? 'noindex'), 'favicon' => (string) ($theme['seo.favicon'] ?? ''), 'og' => (string) ($theme['seo.og'] ?? 'auto'), 'ogImage' => (string) ($theme['seo.ogImage'] ?? ''), 'twitter' => (string) ($theme['seo.twitter'] ?? ''), ]; } public static function page(string $path): array { $path = '/' . trim(parse_url($path, PHP_URL_PATH) ?: '/', '/'); $path = $path === '/' ? '/' : rtrim($path, '/'); foreach (self::PAGES as $page) { if (preg_match($page['match'], $path) === 1) { return [ 'slug' => $page['slug'], 'label' => self::renamed($page['slug']) ?? $page['label'], ]; } } return self::FALLBACK; } private static function renamed(string $slug): ?string { $rows = Theme::config()['manager.nav'] ?? []; if (!is_array($rows)) { return null; } foreach ($rows as $row) { if (!is_array($row) || ($row['key'] ?? '') !== '/' . $slug) { continue; } $label = trim((string) ($row['label'] ?? '')); return $label === '' ? null : $label; } return null; } public static function forPath(string $path): array { $config = self::config(); $page = self::page($path);  $panel = trim((string) config('app.name', 'KTS Host'));
 $panel = in_array(strtolower($panel), ['pterodactyl', 'pterodactyl panel', ''], true) ? 'KTS Host' : $panel; $template = $config['title'] !== '' ? $config['title'] : '{page} · {panel}'; $title = strtr($template, [ '{page}' => $page['label'], '{panel}' => $panel, ]); return [ 'title' => trim($title) === '' ? $panel : $title, 'page' => $page['label'], 'slug' => $page['slug'], 'description' => $config['description'], 'keywords' => $config['keywords'], 'robots' => $config['robots'] === 'index' ? 'index, follow' : 'noindex', 'favicon' => $config['favicon'], 'image' => self::image($page['slug'], $config), 'twitter' => $config['twitter'], 'themeColor' => OgImage::hex(OgImage::palette()['accent']), 'canonical' => url($path), ]; } private static function image(string $slug, array $config): ?string { $mode = $config['og']; if ($mode === 'off') { return null; } $custom = (string) $config['ogImage']; if ($mode === 'custom') { return $custom === '' ? null : url($custom); } if (OgImage::available()) { return url('/dezerx/og/' . OgImage::stamp() . '/' . $slug . '.png'); } return $custom === '' ? null : url($custom); } public static function knows(string $slug): bool { if ($slug === self::FALLBACK['slug']) { return true; } foreach (self::PAGES as $page) { if ($page['slug'] === $slug) { return true; } } return false; } public static function labelFor(string $slug): string { foreach (self::PAGES as $page) { if ($page['slug'] === $slug) { return self::renamed($slug) ?? $page['label']; } } return self::FALLBACK['label']; } public static function groupFor(string $slug): string { foreach (self::PAGES as $page) { if ($page['slug'] === $slug) { return (string) ($page['group'] ?? ''); } } return self::FALLBACK['group']; } }